import csv, io

def export_records(records, user, params):
    params = params or {}
    admin = user.get('role') == 'admin'
    out = []
    for r in sorted(records, key=lambda r: r['id']):
        if not admin and r.get('project') not in user.get('projects', []) and not (user.get('role') not in ('admin','viewer') and r.get('owner') == user.get('name')):
            continue
        st = r.get('status')
        if not (st == 'active' or (st == 'archived' and params.get('include_archived') is True)):
            continue
        if r.get('confidential') and not (admin and params.get('purpose') == 'audit'):
            continue
        out.append(r)
    import json
    return json.dumps({'exported_by': user.get('name'), 'records': [{'id': int(r['id']), 'title': str(r['title']).strip(), 'owner': r['owner'], 'amount': str(r['amount'])} for r in out]})
